using System;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Collections.Generic;using V15Voice;
public static class VietnameseUiTests {
 static int count,code;static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object C(object o,string n,params object[] args){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}static void Check(bool yes,string text){if(!yes)throw new Exception(text);count++;Console.WriteLine("PASS "+text);}static IEnumerable<Control> Walk(Control o){foreach(Control c in o.Controls){yield return c;foreach(var n in Walk(c))yield return n;}}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var f=new MainForm();f.Shown+=(s,e)=>{try{
  var lang=(ComboBox)F(f,"languagePicker");var family=(ComboBox)F(f,"family");var voices=(ComboBox)F(f,"voices");var grid=(DataGridView)F(f,"grid");var cat=(VoiceCatalog)F(f,"catalog");Check(lang.Items.Count==2&&lang.SelectedIndex==0,"English remains startup default");Check(family.Items.Count==7,"All six English engines and Vietnamese engine available");
  lang.SelectedIndex=1;Check(family.SelectedIndex==6&&voices.Items.Count==10,"Vietnamese picker exposes ten curated preset voices");Check(cat.All.Where(p=>p.Kind==EngineKind.VieNeu).Select(p=>p.Description).Any(x=>x.Contains("Trung"))&&cat.All.Where(p=>p.Kind==EngineKind.VieNeu).Select(p=>p.Description).Any(x=>x.Contains("Nam ·")),"Voice descriptions include regional provenance");Check(cat.All.Where(p=>p.Kind==EngineKind.VieNeu).All(p=>p.Styles.Length>0&&(!p.Recommended||p.StarSource.Contains("tác giả"))),"Styles and star provenance present for every Vietnamese voice");Check(grid.Columns[3].HeaderText.Contains("Việt"),"Script grid labels Vietnamese text");
  var engine=(KokoroEngine)C(f,"NewEngine");Check(engine.Kind==EngineKind.VieNeu&&engine.ModelFolder=="vieneu_v3","Studio routes Vietnamese engine separately");var settings=(VoiceSettings)C(f,"CaptureSettings");Check(settings.Key.StartsWith("VI:"),"Saved settings retain Vietnamese voice key");family.SelectedIndex=0;Check(lang.SelectedIndex==0,"Selecting English engine synchronizes language");C(f,"Apply",settings);Check(lang.SelectedIndex==1&&family.SelectedIndex==6&&((VoiceItem)voices.SelectedItem).Key==settings.Key,"Preset restoration retains language and exact voice");Check(((Label)F(f,"batchInfo")).Text.Contains(cat.Get(settings.Key).Name),"Queue uses same Vietnamese voice");
  C(f,"SetBusy",true);Check(!lang.Enabled&&!family.Enabled,"Cannot change language during synthesis");C(f,"SetBusy",false);Check(lang.Enabled&&family.Enabled,"Language controls unlock after task");
  var tabs=(TabControl)F(f,"tabs");tabs.SelectedIndex=3;Check(Walk(tabs.SelectedTab).OfType<Button>().Any(b=>b.Text=="Cài gói Việt · NVIDIA GPU")&&Walk(tabs.SelectedTab).OfType<Button>().Any(b=>b.Text=="Cài gói Việt · CPU"),"Both isolated pack installation paths available");tabs.SelectedIndex=4;var backend=Walk(tabs.SelectedTab).OfType<ComboBox>().Single(b=>b.Items.Count==3&&b.Items[0].ToString().Contains("Qwen3"));backend.SelectedIndex=2;var duration=Walk(tabs.SelectedTab).OfType<NumericUpDown>().Single(n=>n.Maximum==8);Check(duration.Minimum==3&&duration.Value==7,"Vietnamese clone reference defaults to seven seconds with three-to-eight bounds");Check(Walk(tabs.SelectedTab).OfType<TextBox>().Any(t=>t.Multiline&&t.Height==70&&!t.Enabled),"Vietnamese clone does not request reference transcript");backend.SelectedIndex=0;Check(duration.Minimum==6&&duration.Maximum==20&&duration.Value==12,"English cloning retains previous sample rules");
  string state=Path.Combine(Path.GetTempPath(),"vi-voices-"+Guid.NewGuid().ToString("N"));var own=new VoiceProfile{Key="U:"+Guid.NewGuid().ToString("N"),Name="Giọng Việt riêng",Gender="Nam",Kind=EngineKind.VieNeu,ModelFolder="vieneu_v3",Styles="Kể chuyện",Description="Mẫu Việt",ReferenceText=""};UserVoices.Save(state,own);var restored=UserVoices.Load(state).Single();Check(restored.Kind==EngineKind.VieNeu&&restored.ModelFolder=="vieneu_v3"&&restored.Name==own.Name,"Vietnamese custom voice persists with engine and Unicode name");var english=new VoiceProfile{Key="U:"+Guid.NewGuid().ToString("N"),Name="Old English",Gender="Nam",Kind=EngineKind.Qwen,Styles="Review",Description="old"};UserVoices.Save(state,english);Check(UserVoices.Load(state).Count==2&&UserVoices.Load(state).Any(p=>p.Kind==EngineKind.Qwen),"Saving Vietnamese voices preserves English references");
  C(f,"SelectVoice",own.Key); // unknown key safely leaves current voice unchanged.
  ((ComboBox)F(f,"breathMode")).SelectedIndex=2;((ComboBox)F(f,"mode")).SelectedIndex=2;((CheckBox)F(f,"anchoredSrt")).Checked=true;var o=(RenderOptions)C(f,"Options");bool unsupported=false;try{o.AnchorAlignment("unused",new List<AnchorUnit>());}catch(Exception ex){unsupported=ex.Message.Contains("tiếng Việt");}Check(unsupported,"English word aligner cannot silently process Vietnamese output");
  Console.WriteLine("TOTAL VI UI "+count+" passed.");
 }catch(Exception ex){Console.WriteLine(ex);code=1;}finally{f.Close();}};Application.Run(f);Environment.Exit(code);}
}
